/**
 * spriteProduction — the pure production operations for the painted
 * weapon sprites (Top-Choice integration INT-1).
 *
 * The adopted weapon paintings ship as trimmed content sprites in the
 * manifest (src/assets/pixel/sprites/), palette-256 with true alpha.
 * Each carries a trim record (weaponPaintingData.ts, generated by
 * scripts/sync-weapon-paintings.py) stating where its content sits on
 * the adopted master's full canvas. This module owns the three
 * operations on that record:
 *
 *   trimSprite    full-canvas image -> content sprite
 *   untrimSprite  content sprite -> full-canvas image (its inverse)
 *   retrimSprite  full-canvas image -> its measured trim record
 *
 * The round-trip law — untrim then re-measure returns the record, and
 * trim of untrim is pixel-identical — is pinned for every production
 * sprite by src/test/weaponKinds.test.ts.
 *
 * Deliberately pure (no Vite imports, no manifest loading): the wiki
 * generator and the test suite load this module in Node, the same
 * constraint legendaryArt.ts lives under. No game renderer consumes
 * these sprites yet; see docs/top-choice-weapon-integration.md.
 */
import type { RgbaImage } from './pngCodec';
import {
  LEGENDARY_PAINTING_SLUGS,
  WEAPON_BASE_PAINTING_STEMS,
  WEAPON_PAINTING_TRIMS,
  type WeaponPaintingTrim,
} from './weaponPaintingData';

export type { WeaponPaintingTrim };
export { LEGENDARY_PAINTING_SLUGS, WEAPON_BASE_PAINTING_STEMS };

/** Content threshold: the derivation recipe's alpha > 8 content box. */
export const SPRITE_CONTENT_ALPHA = 8;

/** Manifest sprite id for a legendary painting slug. The bespoke
 *  `legendary-<slug>` ids are the V4 authored-data identities and are
 *  NOT sprites (pinned by pixelManifest.test.ts); paintings live in
 *  their own id space beside them. */
export function legendaryPaintingSpriteId(slug: string): string {
  return `legendary-painting-${slug}`;
}

/** Manifest sprite id for a weapon base painting, by wiki frame stem. */
export function weaponBaseSpriteId(stem: string): string {
  return `weapon-base-${stem}`;
}

/** The trim record for a painting sprite id; throws on unknown ids. */
export function weaponPaintingTrim(spriteId: string): WeaponPaintingTrim {
  const trim = WEAPON_PAINTING_TRIMS[spriteId];
  if (!trim) throw new Error(`spriteProduction: no trim record for sprite "${spriteId}"`);
  return trim;
}

/** Crop the (left, top, width, height) content box out of a full-canvas image. */
export function trimSprite(
  img: RgbaImage,
  trim: WeaponPaintingTrim,
  width: number,
  height: number,
): RgbaImage {
  if (trim.left + width > img.width || trim.top + height > img.height) {
    throw new Error(
      `spriteProduction: trim box (${trim.left}, ${trim.top}, ${width}x${height}) exceeds canvas ${img.width}x${img.height}`,
    );
  }
  const data = new Uint8Array(width * height * 4);
  for (let y = 0; y < height; y++) {
    const srcRow = ((trim.top + y) * img.width + trim.left) * 4;
    data.set(img.data.subarray(srcRow, srcRow + width * 4), y * width * 4);
  }
  return { width, height, data };
}

/** Place a trimmed sprite back onto its full canvas over transparency. */
export function untrimSprite(sprite: RgbaImage, trim: WeaponPaintingTrim): RgbaImage {
  if (trim.left + sprite.width > trim.fullWidth || trim.top + sprite.height > trim.fullHeight) {
    throw new Error(
      `spriteProduction: sprite ${sprite.width}x${sprite.height} at (${trim.left}, ${trim.top}) exceeds full canvas ${trim.fullWidth}x${trim.fullHeight}`,
    );
  }
  const data = new Uint8Array(trim.fullWidth * trim.fullHeight * 4);
  for (let y = 0; y < sprite.height; y++) {
    const dstRow = ((trim.top + y) * trim.fullWidth + trim.left) * 4;
    data.set(
      sprite.data.subarray(y * sprite.width * 4, (y + 1) * sprite.width * 4),
      dstRow,
    );
  }
  return { width: trim.fullWidth, height: trim.fullHeight, data };
}

export interface RetrimResult {
  trim: WeaponPaintingTrim;
  /** Content box size — the trimmed sprite's dimensions. */
  width: number;
  height: number;
}

/**
 * Measure a full-canvas image's trim record from its alpha mask:
 * content is alpha > SPRITE_CONTENT_ALPHA, the derivation recipe's
 * threshold. Throws on a fully transparent image.
 */
export function retrimSprite(img: RgbaImage): RetrimResult {
  let left = img.width;
  let top = img.height;
  let right = -1;
  let bottom = -1;
  for (let y = 0; y < img.height; y++) {
    for (let x = 0; x < img.width; x++) {
      if (img.data[(y * img.width + x) * 4 + 3] > SPRITE_CONTENT_ALPHA) {
        if (x < left) left = x;
        if (x > right) right = x;
        if (y < top) top = y;
        if (y > bottom) bottom = y;
      }
    }
  }
  if (right < 0) throw new Error('spriteProduction: retrim of a fully transparent image');
  return {
    trim: { fullWidth: img.width, fullHeight: img.height, left, top },
    width: right - left + 1,
    height: bottom - top + 1,
  };
}
